// Command gen writes web/examples.js from the example list in
// internal/playground. Run it with `make generate`.
package main

import (
	"fmt"
	"os"

	"github.com/polyql/polyql/internal/playground"
	"github.com/polyql/polyql/pkg/registry"

	// Imported for their registration side effects, matching the browser build:
	// the examples must be generated by the same set of languages the page can
	// translate between.
	_ "github.com/polyql/polyql/pkg/compiler/emitter/logql"
	_ "github.com/polyql/polyql/pkg/compiler/emitter/promql"
	_ "github.com/polyql/polyql/pkg/compiler/emitter/traceql"
	_ "github.com/polyql/polyql/pkg/compiler/parser/logql"
	_ "github.com/polyql/polyql/pkg/compiler/parser/promql"
	_ "github.com/polyql/polyql/pkg/compiler/parser/traceql"
)

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: gen <output-path>")
		os.Exit(2)
	}

	reg, err := registry.DefaultRegistry()
	if err != nil {
		fail(err)
	}
	content, err := playground.Generate(reg)
	if err != nil {
		fail(err)
	}
	if err := os.WriteFile(os.Args[1], content, 0o644); err != nil {
		fail(err)
	}
}

func fail(err error) {
	fmt.Fprintln(os.Stderr, "gen: "+err.Error())
	os.Exit(1)
}
